const $=s=>document.querySelector(s);
const networks=[{id:'instagram',name:'Instagram',type:'Creator account',icon:'◎',note:'Use a photo or video. A vertical composition can work well for Reels.'},{id:'tiktok',name:'TikTok',type:'Personal account',icon:'♪',note:'Use a video or supported photo post. Preview your vertical composition before publishing.'},{id:'facebook',name:'Facebook',type:'Facebook Page',icon:'f',note:'Text, photos, and videos can each tell your story on your Page.'},{id:'x',name:'X',type:'Your profile',icon:'𝕏',note:'Keep captions concise. Account-specific text and media limits will be checked after connection.'}];
let active='instagram',overrides={},mediaUrl='',mediaFile=null,editing=null,drafts=[];
const key='connectors-drafts-v1';
try{const loaded=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(loaded))drafts=loaded.filter(d=>d&&typeof d.id==='string'&&typeof d.text==='string'&&Array.isArray(d.channels)&&d.channels.every(c=>networks.some(n=>n.id===c)));}catch{toast('Saved drafts could not be loaded. Browser storage may be unavailable.');}
function toast(message){$('#toast').textContent=message;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').textContent='',5500);}
function go(id){document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==id);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===id));$('#breadcrumb').textContent=document.querySelector(`[data-view="${id}"] span`).textContent;if(id==='calendar'||id==='status')renderDrafts();}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>go(b.dataset.view));
networks.forEach(n=>{const label=document.createElement('label');label.className='channel';const check=document.createElement('input');check.type='checkbox';check.value=n.id;check.checked=true;label.append(check,document.createTextNode(n.name));$('#channels').append(label);const tab=document.createElement('button');tab.type='button';tab.textContent=n.name;tab.dataset.platform=n.id;tab.onclick=()=>{active=n.id;$('#override').value=overrides[active]||'';preview();};$('#preview-tabs').append(tab);const card=document.createElement('article');card.className='panel account-card';const title=document.createElement('h2');title.textContent=n.icon+' '+n.name;const type=document.createElement('p');type.textContent=n.type;const badge=document.createElement('span');badge.className='badge';badge.textContent='NOT CONNECTED';card.append(title,type,badge);$('#account-grid').append(card);});
function preview(){const n=networks.find(n=>n.id===active);$('#preview-icon').textContent=n.icon;$('#preview-name').textContent=n.name+' · '+n.type;$('#preview-text').textContent=overrides[active]||$('#caption').value||'Your story, in your own words.';$('#count').textContent=$('#caption').value.length+' characters';$('#format-note').textContent=n.note+(!mediaFile&&['instagram','tiktok'].includes(active)?' Add media before publishing to this channel.':'');document.querySelectorAll('[data-platform]').forEach(b=>{b.classList.toggle('active',b.dataset.platform===active);b.setAttribute('aria-pressed',b.dataset.platform===active);});}
$('#caption').oninput=preview;$('#override').oninput=()=>{overrides[active]=$('#override').value;preview();};
const mediaPlaceholder=$('#preview-media').innerHTML;
function clearMedia(){if(mediaUrl)URL.revokeObjectURL(mediaUrl);mediaUrl='';mediaFile=null;$('#media').value='';$('#preview-media').innerHTML=mediaPlaceholder;$('#media-info').replaceChildren();}
$('#media').onchange=()=>{const file=$('#media').files[0];if(!file)return;if(file.size>50*1024*1024||!['image/jpeg','image/png','image/webp','video/mp4','video/webm'].includes(file.type)){toast('Choose a JPG, PNG, WebP, MP4, or WebM file under 50 MB.');$('#media').value='';return;}clearMedia();mediaFile=file;mediaUrl=URL.createObjectURL(file);const el=document.createElement(file.type.startsWith('video/')?'video':'img');el.src=mediaUrl;if(el.tagName==='VIDEO'){el.controls=true;el.playsInline=true;}else el.alt='Selected post media';$('#preview-media').replaceChildren(el);const remove=document.createElement('button');remove.type='button';remove.className='subtle';remove.textContent='Remove';remove.onclick=()=>{clearMedia();preview();};$('#media-info').append(document.createTextNode(file.name+' · Ready to upload when you confirm publishing. Reselect media when reopening a draft. '),remove);preview();};
$('#timezone').textContent='Times shown in '+Intl.DateTimeFormat().resolvedOptions().timeZone;
function persist(next){try{localStorage.setItem(key,JSON.stringify(next));drafts=next;return true;}catch{toast('Unable to save. Browser storage is unavailable or full.');return false;}}
$('#post-form').onsubmit=e=>{e.preventDefault();const text=$('#caption').value.trim(),channels=[...document.querySelectorAll('#channels input:checked')].map(c=>c.value),date=$('#date').value;if(!channels.length)return toast('Select at least one channel.');if(!text&&!mediaFile&&!Object.values(overrides).some(v=>v.trim()))return toast('Write a caption or add media first.');if(date&&(!Number.isFinite(new Date(date).getTime())||new Date(date)<=new Date()))return toast('Choose a future time for this draft.');const draft={id:editing||crypto.randomUUID(),text,channels,date,overrides:{...overrides},mediaName:mediaFile?.name||'',updated:new Date().toISOString()};const next=[draft,...drafts.filter(d=>d.id!==editing)];if(!persist(next))return;editing=null;$('#post-form').reset();document.querySelectorAll('#channels input').forEach(c=>c.checked=true);overrides={};$('#override').value='';clearMedia();preview();go('status');toast('Draft saved locally. Nothing has been published.');};
function renderDrafts(){renderList($('#draft-list'),drafts,false);renderList($('#calendar-list'),[...drafts].filter(d=>d.date).sort((a,b)=>new Date(a.date)-new Date(b.date)),true);}
function renderList(container,list,calendar){container.replaceChildren();if(!list.length){const empty=document.createElement('div');empty.className='empty';empty.textContent=calendar?'No planned posts yet. Add a date when saving your next draft.':'A fresh start. Create your first draft to see it here.';container.append(empty);return;}list.forEach(d=>{const card=document.createElement('article');card.className='panel draft';const title=document.createElement('h2');title.textContent=d.date?new Date(d.date).toLocaleString():'Unscheduled draft';const caption=document.createElement('p');caption.textContent=d.text||'Media or channel-specific post';const meta=document.createElement('small');meta.textContent=d.channels.map(c=>networks.find(n=>n.id===c).name).join(' · ')+' — Draft only'+(d.mediaName?' · Reselect media: '+d.mediaName:'');const edit=document.createElement('button');edit.textContent='Edit draft';edit.onclick=()=>{editing=d.id;$('#caption').value=d.text;$('#date').value=d.date||'';overrides={...(d.overrides||{})};$('#override').value=overrides[active]||'';document.querySelectorAll('#channels input').forEach(c=>c.checked=d.channels.includes(c.value));clearMedia();preview();go('create');if(d.mediaName)toast('Reselect your media file to preview it.');};const del=document.createElement('button');del.textContent='Delete draft';del.onclick=()=>{if(persist(drafts.filter(x=>x.id!==d.id))){renderDrafts();toast('Draft deleted.');}};card.append(title,caption,meta,edit,del);container.append(card);});}
preview();
